def render_numbers(x):
 if isinstance(x,str):return re.sub(r'\\tag\{([^}]+)\}',r'\\quad\\text{(\1)}',x)
 if isinstance(x,list):return [render_numbers(v) for v in x]
 if isinstance(x,dict):return {k:render_numbers(v) for k,v in x.items()}
 return x
CONTENT=render_numbers(CONTENT)
for name,data in [('content.json',CONTENT),('symbols.json',dict(paper_id=pid,symbols=CONTENT['symbols'])),('issues.json',dict(paper_id=pid,issues=CONTENT['issues']))]:
 (P/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
